css:
.row {
  display: flex;
  gap: 12px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.btn {
  padding: 8px 16px;
  border: 0;
  border-radius: 6px;
  background-color: #f97316;
  color: #ffffff;
  font: inherit;
  cursor: pointer;
}

.btn:hover {
  background-color: #ea580c;
}

.btn:active {
  background-color: #c2410c;
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

.btn[aria-disabled="true"] {
  background-color: #d4d4d8;
  color: #71717a;
  cursor: not-allowed;
}
